  name: string;
  description?: string;
  owner?: string;
  plugins: Array<{
    name: string;
    description?: string;
    author?: string;
    category?: string;
    homepage?: string;
    /** Declared in the manifest when present — often absent (CC has no version convention). */
    version?: string;
  }>;
